from dataclasses import dataclass
from datetime import datetime

from sqlalchemy import DateTime, Integer, String, Text
from sqlalchemy.orm import Mapped, mapped_column

from opentakserver.extensions import db
from opentakserver.functions import iso8601_string_from_datetime


@dataclass
class SearchSector(db.Model):
    """Civil SAR search sector polygon (ПСР). Stored as a closed ring of lat/lon."""

    __tablename__ = "search_sectors"

    id: Mapped[int] = mapped_column(Integer, primary_key=True)
    uid: Mapped[str] = mapped_column(String(255), unique=True, nullable=False)
    name: Mapped[str] = mapped_column(String(255), nullable=False, default="Sector")
    assigned_to: Mapped[str] = mapped_column(String(255), nullable=True)
    mission_name: Mapped[str] = mapped_column(String(255), nullable=True)
    status: Mapped[str] = mapped_column(String(32), nullable=False, default="active")
    # JSON array of [lat, lon] pairs
    coordinates: Mapped[str] = mapped_column(Text, nullable=False, default="[]")
    cot_uid: Mapped[str] = mapped_column(String(255), nullable=True)
    created: Mapped[datetime] = mapped_column(DateTime, nullable=True)
    updated: Mapped[datetime] = mapped_column(DateTime, nullable=True)

    def to_json(self):
        import json

        try:
            coords = json.loads(self.coordinates or "[]")
        except Exception:
            coords = []
        return {
            "uid": self.uid,
            "name": self.name,
            "assigned_to": self.assigned_to,
            "mission_name": self.mission_name,
            "status": self.status,
            "coordinates": coords,
            "cot_uid": self.cot_uid or self.uid,
            "created": iso8601_string_from_datetime(self.created) if self.created else None,
            "updated": iso8601_string_from_datetime(self.updated) if self.updated else None,
        }
